        question: 'What did the people of Quraysh say when the Prophet \uFDFA asked if they would believe him about an approaching army?',
        questionAr: 'ماذا قال أهل قريش حين سألهم النبي \uFDFA لو أخبرهم بجيش قادم هل يصدّقونه؟',
        options: [
