          '"It depends on who else confirms it"',
        ],
        optionsAr: [
          '"نحتاج أن نرى دليلاً أولاً"',
          '"نعم، ما جرّبنا عليك كذباً قط"',
          '"يعتمد على من يؤكد ذلك"',
        ],
        correctIndex: 1,
        explanation: 'History records — The entire crowd, including his future enemies, confirmed they had never known him to lie. Forty years of honesty earned him the right to deliver the hardest message any of them would ever hear. Their own testimony became evidence against them when they later rejected him.',
        explanationAr: 'يسجّل التاريخ — الجمع كله بمن فيهم أعداؤه المستقبليون أكدوا أنهم لم يعرفوا عنه كذباً قط. أربعون عاماً من الصدق منحته حق إيصال أصعب رسالة سيسمعونها. وشهادتهم أنفسهم صارت حجة عليهم حين رفضوه لاحقاً.',
        sourceRef: 'Sahih Bukhari 4971',
        sourceRefAr: 'صحيح البخاري 4971',
      ),
    ],
  ),

